65:    const clock = new FakeClock();
66:    const store = new FakeStore(clock);
67:    store.failNext = 1;
68:    const buffer = { text: "" };
69:    const saver = new DraftAutosaver(() => buffer.text, store, clock, 1000);
70:    run(saver, clock, buffer, new Map([[0, "draft v1"]]), 4000);
71:    assertEqual(store.last(), "draft v1", "last saved draft");
72:  }],
73:];
