75:let failed = 0;
76:for (const [name, fn] of cases) {
77:  try {
78:    fn();
79:    console.log(`ok   - ${name}`);
80:  } catch (e) {
81:    failed++;
82:    console.log(`FAIL - ${name}: ${e instanceof Error ? e.message : String(e)}`);
83:  }
84:}
85:console.log(failed === 0 ? "all passed" : `${failed} failed`);
86:process.exitCode = failed === 0 ? 0 : 1;

